+++ b/frontend/src/jest.shard-sequencer.test.js
@@ -0,0 +1,40 @@
+const BazelShardSequencer = require("../jest.shard-sequencer.cjs");
+
+describe("BazelShardSequencer", () => {
+  const originalTotal = process.env.TEST_TOTAL_SHARDS;
+  const originalIndex = process.env.TEST_SHARD_INDEX;
+
+  beforeEach(() => {
+    process.env.TEST_TOTAL_SHARDS = "4";
+    process.env.TEST_SHARD_INDEX = "1";
+  });
+
+  afterAll(() => {
+    if (originalTotal === undefined) {
+      delete process.env.TEST_TOTAL_SHARDS;
+    } else {
+      process.env.TEST_TOTAL_SHARDS = originalTotal;
+    }
+    if (originalIndex === undefined) {
+      delete process.env.TEST_SHARD_INDEX;
+    } else {
+      process.env.TEST_SHARD_INDEX = originalIndex;
+    }
+  });
+
+  it("does not partition Jest's already-sharded failed-test list again", () => {
+    const tests = [
+      { path: "/missing/c.test.js" },
+      { path: "/missing/a.test.js" },
+      { path: "/missing/b.test.js" },
+    ];
+    const sequencer = new BazelShardSequencer();
+
+    expect(sequencer.sort(tests).map((test) => test.path)).toEqual(["/missing/b.test.js"]);
+    expect(sequencer.allFailedTests(tests).map((test) => test.path)).toEqual([
+      "/missing/a.test.js",
+      "/missing/b.test.js",
+      "/missing/c.test.js",
+    ]);
+  });
+});

